import {pathways,pathwayProgress} from './curriculum.js';
import {transferPlan,beginTransfer,transferTrials,transferSatisfied} from './transfers.js';
import {checkpoint,chooseAnswer,storeFeedback,advanceRun,beginRetry,beginReview,selectedTrials,toggleTrialSelection,hasSelectedFairPair,enterStage,migrateRun} from './controller.js';
import {regions,missions,byId,glossary,Q} from './content.js';
import {adapters,simulate,round,insideBay,validEnergyConstruction} from './models.js';
import {CATEGORIES,skillState,recordCheck,fairPair,createRun,makeProfile,validateSave} from './learning.js';
import {openStore,loadSave,persist,getEvents,importEvents,deleteProfileEvents,replaceSaveWithEvents,recoveryExport,archiveUnreadableSave} from './storage.js';
import {scene,chart,esc,robot} from './visuals.js';
const $=s=>document.querySelector(s);const app=$('#app');
let data,storageMode,ui={view:'explore',region:'motion',mission:'rover-rescue',feedback:null,choice:null,animation:null,progress:0,paused:false,lab:{adapter:'ramp',input:.2,trials:[],options:{},coop:false},arcade:null},saveError=false,swUpdate=null;
const profile=()=>data.profiles.find(p=>p.id===data.active);
const currentMission=()=>byId[ui.mission];
const currentRun=()=>profile().runs[ui.mission];
const button=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
const regionOf=m=>regions.find(r=>r.id===m.region);
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function save(type='checkpoint',payload={}){try{await persist(data,{profile:data.active,mission:ui.mission,type,...payload});saveError=false;const status=$('#save-status');if(status)status.textContent='Saved on this device';}catch(error){saveError=true;notify('Progress could not be saved. Export a backup in Settings before closing.');const status=$('#save-status');if(status)status.textContent='Save failed — export a backup';}}
function goto(view,extras={}){stopAnimation();Object.assign(ui,{view,feedback:null,choice:null,progress:0},extras);if(view!=='mission')save('navigation');render();window.scrollTo({top:0,behavior:'instant'});$('#main')?.focus({preventScroll:true});}
function startMission(id){if(!byId[id])return;ui.mission=id;profile().runs[id]??=createRun(byId[id]);const r=migrateRun(profile().runs[id]);if(r.stage==='done')ui.progress=1;data.lastMission=id;profile().lastMission=id;save('mission-open');goto('mission',{mission:id,progress:r.trials.length?1:0,choice:checkpoint(r).choice,feedback:checkpoint(r).feedback});}
function achievements(){return missions.filter(m=>profile().runs[m.id]?.completed).length;}
function shell(body){let p=profile();return `<div class="game-shell"><header class="topbar"><button class="brand" data-action="nav" data-view="explore" aria-label="Science Quest home"><span class="brand-mark">✦</span><span>SCIENCE <strong>QUEST</strong><small>DISCOVERY ISLANDS</small></span></button><div class="top-actions"><span class="discovery-count">✧ ${achievements()}<span> discoveries</span></span><button class="profile-button" data-action="nav" data-view="settings"><span>${esc(p.avatar)}</span> ${esc(p.name)}</button><button class="icon-button" data-action="nav" data-view="settings" aria-label="Settings">⚙</button></div></header>${!navigator.onLine?'<div class="offline">Offline exploration · progress saves on this device</div>':''}${swUpdate?`<div class="offline">An island update is ready. ${button('Save & update','update')}</div>`:''}<main id="main" tabindex="-1">${body}</main><nav class="bottom-nav" aria-label="Game modes">${[['explore','⌖','Explore'],['lab','⚒','Build'],['test','▷','Test'],['journal','▤','Journal'],['arcade','✧','Arcade']].map(([id,icon,name])=>`<button data-action="nav" data-view="${id}" class="${ui.view===id||(id==='test'&&ui.view==='mission')||(id==='explore'&&ui.view==='region')?'active':''}" ${ui.view===id?'aria-current="page"':''}><span>${icon}</span>${name}</button>`).join('')}</nav><footer><span id="save-status">${saveError?'Save failed — export a backup':'Saved on this device'}</span><span>Science Quest 1.2 · Early access</span></footer></div>`;}
function heading(eyebrow,title,copy='',actions=''){return `<div class="section-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${copy?`<p class="intro">${copy}</p>`:''}</div>${actions}</div>`;}
function recommended(){const last=profile().lastMission||data.lastMission;return (last&&!profile().runs[last]?.completed?byId[last]:null)||(data.settings.band!=='All explorers'?missions.find(m=>m.band===data.settings.band&&!profile().runs[m.id]?.completed):null)||missions.find(m=>m.id==='rover-rescue'&&!profile().runs[m.id]?.completed)||missions.find(m=>!profile().runs[m.id]?.completed)||byId['rover-rescue'];}
function mapView(){const next=recommended();return `<section class="world-wrap"><div class="world-top"><div><p class="eyebrow">YOUR NEXT GREAT DISCOVERY</p><h1>A little curiosity.<br>A whole world to restore.</h1></div><span class="world-weather">☀ &nbsp; A good day for science</span></div><div class="world-map"><img class="island-art" src="./assets/islands.webp" alt="A research archipelago with a rover harbor, materials workshop, biodome, weather ridge, signal lighthouse and observatory connected by bridges." fetchpriority="high"><div class="map-vignette"></div><div class="map-label">DISCOVERY ISLANDS <span>FIELD MAP / 01</span></div>${regions.map(r=>{const count=missions.filter(m=>m.region===r.id&&profile().runs[m.id]?.completed).length;return `<button class="map-pin ${count?'restored':''}" style="left:${r.x}%;top:${r.y}%;--region:${r.color}" data-action="region" data-id="${r.id}" aria-label="Explore ${r.name}, ${count} discoveries"><i>${r.icon}</i><span>${r.name}<small>${count?`${count} discoveries made`:'Explore region →'}</small></span></button>`;}).join('')}<div class="map-coordinate">27.4° N &nbsp; / &nbsp; 6 RESEARCH REGIONS</div><div class="recommend"><span class="mission-emblem">${regionOf(next).icon}</span><div><p class="eyebrow">${profile().runs[next.id]&&!profile().runs[next.id].completed?'CONTINUE YOUR EXPEDITION':'PIP’S PICK'}</p><h2>${esc(next.title)}</h2><p>Make a prediction. Build. Test. Discover.</p></div>${button(profile().runs[next.id]&&!profile().runs[next.id].completed?'Resume mission →':'Start mission →','start','primary',`data-id="${next.id}"`)}</div></div><div class="under-map"><div class="pip-mini">${robotSvg()}<p><strong>“Every good question is a place to start.”</strong><br>I’m Pip, your field assistant. Pick an island or join me at the rover ramp.</p></div><div>${button('Learning pathways →','nav','secondary','data-view="courses"')}${button('Meet the islands ↓','islands','text-button')}</div></div><div id="region-grid" class="region-grid">${regions.map(r=>`<button class="region-card" data-action="region" data-id="${r.id}" style="--region:${r.color}"><span class="region-icon">${r.icon}</span><strong>${r.name}</strong><span>${r.description}</span><small>${missions.filter(m=>m.region===r.id).length} missions &nbsp; →</small></button>`).join('')}</div></section>`;}
function robotSvg(){return `<svg viewBox="0 0 80 85" class="pip-icon" aria-hidden="true">${robot(40,40)}</svg>`;}
function coursesView(){return `<section class="content">${heading('CHOOSE YOUR ROUTE','Learning pathways','Start where you are ready. Grade labels guide the route; every guided mission remains available.')}<div class="course-grid">${pathways.map(p=>{const progress=pathwayProgress(p,profile());return `<article class="mission-card"><div class="card-top">${badge('Grade '+p.grade)}${badge(progress.completed+' / '+progress.total+' investigations')}</div><h2>${p.title}</h2><p>${p.focus}</p><ol class="course-missions">${p.missions.map(id=>{const m=byId[id],r=profile().runs[id];return `<li>${button((r?.completed?'✓ ':'')+m.title,'start','text-button',`data-id="${id}"`)}<small>${skillState(r)}</small></li>`;}).join('')}</ol><details class="model-card"><summary>Course scope and development</summary><p>This route currently covers the investigations above, not a complete grade curriculum. Still being developed: ${p.next.join('; ')}.</p></details></article>`;}).join('')}</div></section>`;}
function regionView(){const r=regions.find(r=>r.id===ui.region),list=missions.filter(m=>m.region===r.id),count=list.filter(m=>profile().runs[m.id]?.completed).length;return `<section class="content">${button('← Discovery Islands','nav','back','data-view="explore"')}${heading('FIELD EXPEDITION',r.name,r.description,`<div class="region-heading-icon" style="background:${r.color}">${r.icon}</div>`)}<div class="region-banner" style="--region:${r.color}"><div><b>${count===list.length?r.reward:'Restore this part of the island network'}</b><p>${count} of ${list.length} discoveries · Guided missions are always available.</p></div><progress value="${count}" max="${list.length}" aria-label="Region restoration"></progress></div><div class="mission-grid">${list.map(m=>{const run=profile().runs[m.id],s=skillState(run);return `<article class="mission-card"><div class="card-top"><span class="mission-number">${String(m.index+1).padStart(2,'0')}</span>${badge(run?.completed?'✓ Discovery made':m.band+' pathway',run?.completed?'success':'')}</div><h2>${m.title}</h2><p>${m.story}</p><div class="mission-meta">${m.minutes} min · ${m.skill}</div><div class="card-foot">${badge(s,s==='Demonstrated'||s==='Retained'?'success':'')}${button(run&&!run.completed?'Resume →':run?.completed?'Revisit →':'Explore →','start','secondary',`data-id="${m.id}"`)}</div></article>`;}).join('')}</div></section>`;}
function questionFor(m,r){const stage=r.stage;let q;
 if(stage==='predict')q=r.attempts.predict>0?m.questions.t1:m.questions.predict;
 if(stage==='build')q=Q(`Which setup makes a fair test of ${adapters[m.adapter].control}?`,`Change only ${adapters[m.adapter].control}; keep the other conditions the same.`,`Change ${adapters[m.adapter].control} and the starting object together.`,'Change every setting to see a bigger difference.');
 if(stage==='compare'){const pair=selectedTrials(r);if(pair.length===2){const [a,b]=pair;const relation=b.value>a.value?'greater than':b.value<a.value?'less than':'equal to';q=Q(`Compare Trial ${r.trials.indexOf(a)+1} and Trial ${r.trials.indexOf(b)+1}. The measured ${adapters[m.adapter].output.toLowerCase()} in the second is…`,`${relation} the first.`,`${relation==='greater than'?'less than':'greater than'} the first.`,'Impossible to compare using the recorded measurements.');}}
 if(stage==='explain')q=r.attempts.explain>0?m.questions.t2:m.questions.explain;
 if(stage==='transfer1')q=m.questions.t1;
 if(stage==='transfer2')q=m.questions.t2;
 return q;
}
function choices(q,r){if(!q)return '';const rotation=(currentMission().index+r.stage.length+(r.attempts[r.stage]||0))%q.options.length;const options=q.options.map((text,i)=>({text,i}));options.push(...options.splice(0,rotation));return `<div class="question"><h2>${esc(q.prompt)}</h2><div class="choices" role="group" aria-label="Answer choices">${options.map(o=>`<button class="choice ${ui.choice===o.i?'selected':''}" data-action="choice" data-value="${o.i}" aria-pressed="${ui.choice===o.i}"><span class="choice-dot">${ui.choice===o.i?'●':'○'}</span>${esc(o.text)}</button>`).join('')}</div></div>`;}
function lesson(m){if(m.lesson)return m.lesson;const lessons={ramp:'Watch a rover roll down a ramp. Starting higher gives it more gravitational energy to transfer into motion. On the same stopping lane, a higher start goes farther. A fair test changes height only.',push:'A contact push is a force. It can change motion. Compare a gentle and a stronger push on the same cart for the same amount of time. Start each trial from rest.',direction:'A push has a direction as well as a strength. Start a cart at rest and push left, then reset and push right. A direction test keeps strength, duration and the cart unchanged.',force:'Opposing forces act in different directions. Equal opposing forces give zero net force. A resting cart stays at rest; an already-moving cart keeps its velocity in our resistance-free model.',resistance:'Rolling resistance acts against motion and slows the rover. At the same entry speed, stronger resistance brings it to rest sooner. Its energy transfers to the surroundings.',collision:'A moving cart has kinetic energy. For equal masses, a faster cart carries more. When a soft barrier stops it, energy transfers into deformation, heating and sound.',thermal:'Warm and cool regions can transfer energy through a material. Conductivity describes how readily that transfer occurs. A lower conductivity gives less heat transfer each second for the same wall and temperatures.',matter:'Choose the system boundary: everything inside our sealed container. If nothing enters or leaves, the total mass of the contents is conserved when they are mixed or change state.',plant:'Plants need suitable conditions. Our fictional species grows best at an intermediate light level, not at the highest possible light. Compare three plants per condition while keeping water, soil and temperature unchanged.',habitat:'An organism needs resources. A food budget compares available food with food needed by each animal. Real habitats also involve water, shelter and interactions; food alone cannot predict a population.',runoff:'Rainwater can run across a surface or stay in the ground. Our model gives more retention with more vegetation. Keep rain, soil and slope fixed when testing cover.',wave:'A wave repeats. Frequency counts cycles per second; wavelength is the distance between corresponding points on consecutive cycles. At a fixed speed, higher frequency means shorter wavelength.',energy:'Power is an energy-transfer rate, measured in watts. Energy in watt-hours equals watts multiplied by hours. Only a fraction of the stored energy reaches the loads; the rest transfers to the surroundings.',orbit:'An orbit repeats around a central body. In this circular-orbit model around a Sun-like star, larger radii have longer periods. The relationship changes if the central mass changes.'};return lessons[m.adapter];}
function trialTable(trials,adapter,compact=false){const model=adapters[adapter];if(!trials.length)return '<p class="empty">Your results will appear here after your first test.</p>';return `<div class="table-scroll"><table><caption class="sr-only">Recorded experiment measurements</caption><thead><tr><th>Trial</th><th>${model.input} ${model.unit?`(${model.unit})`:''}</th><th>${model.output} (${model.outUnit})</th>${compact?'':'<th>Replay</th>'}</tr></thead><tbody>${trials.map((t,i)=>`<tr><th scope="row">${i+1}</th><td>${round(t.input)}</td><td>${round(t.value)}</td>${compact?'':`<td><button class="tiny" data-action="replay" data-index="${i}" aria-label="Replay trial ${i+1}">▷</button></td>`}</tr>`).join('')}</tbody></table></div>`;}
function timeSeries(result,adapter){if(result?.genotypes)return `<details class="model-card"><summary>Offspring probability table</summary><table><caption>Expected genotype proportions</caption><thead><tr><th>Genotype</th><th>Probability</th></tr></thead><tbody>${Object.entries(result.genotypes).map(([g,p])=>`<tr><th>${g}</th><td>${p}%</td></tr>`).join('')}</tbody></table><p>Expected proportions do not guarantee exact small-group outcomes.</p></details>`;if(adapter==='diffusion'&&result)return `<details class="model-card"><summary>Membrane exchange record</summary><table><caption>Dye concentration, units/L, in two one-litre compartments</caption><thead><tr><th>Time (s)</th><th>Inside</th><th>Outside</th></tr></thead><tbody>${result.series.filter((_,i)=>i%10===0).map(p=>`<tr><td>${p.t}</td><td>${round(p.x)}</td><td>${round(p.outside)}</td></tr>`).join('')}</tbody></table><p>Total dye: ${result.total} units. Equilibrium concentration: ${result.value} units/L in both compartments.</p></details>`;if(adapter==='circuit'&&result)return `<details class="model-card"><summary>Circuit measurements</summary><p>Current: ${round(result.value)} A. Power transferred to resistor: ${round(result.power)} W. Source voltage: 6 V.</p></details>`;if(adapter==='density'&&result)return `<p class="model-card">The sample ${result.state==='floats'?'floats':result.state==='neutral'?'is neutrally buoyant':'sinks'}. Fully submerged is not the same as floating.</p>`;if(!result||!['plant','energy','wave','orbit'].includes(adapter))return '';const m=adapters[adapter];let rows=result.series;if(rows.length>15)rows=rows.filter((_,i)=>i%10===0);return `<details class="model-card"><summary>${adapter==='plant'?'Daily growth record & replicates':'Model data record'}</summary><div class="table-scroll"><table><thead><tr><th>${result.timeUnit||'Model time (s)'}</th><th>${adapter==='wave'?'Displacement (relative)':adapter==='orbit'?'x-position (AU)':adapter==='energy'?'Delivered energy balance (Wh)':'Mean height (cm)'}</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${round(p.t)}</td><td>${round(p.x)}</td></tr>`).join('')}</tbody></table></div>${result.replicates?`<p>Day 7 replicates: ${result.replicates.map(x=>round(x)+' cm').join(' · ')}. Mean ${round(result.value)} cm.</p>`:''}${adapter==='energy'?`<p>Delivered: ${result.delivered} Wh · demand: ${result.demand} Wh · conversion transfer to surroundings: ${result.loss} Wh.</p>`:''}</details>`;}
function controls(adapter,input,locked=false,options={}){const m=adapters[adapter];return `<div class="controls"><div class="control-label"><label for="experiment-input">${m.input}</label><output id="input-output">${input} ${m.unit}</output></div><div class="slider-row">${button('−','adjust','adjust',`data-delta="-1" aria-label="Decrease ${m.input}" ${locked?'disabled':''}`)}<input id="experiment-input" type="range" min="${m.min}" max="${m.max}" step="${m.step}" value="${input}" ${locked?'disabled':''} aria-label="${m.input}">${button('+','adjust','adjust',`data-delta="1" aria-label="Increase ${m.input}" ${locked?'disabled':''}`)}</div><div class="range-ends"><span>${m.min} ${m.unit}</span><span>${m.max} ${m.unit}</span></div><p class="fixed">⌑ ${adapter==='ramp'&&options.resistance?m.fixed+' · Free Lab resistance override: '+options.resistance:m.fixed}</p></div>`;}
function modelCard(adapter){const m=adapters[adapter];return `<details class="model-card"><summary>Model assumptions & science notes</summary><p>${m.limits}</p><details><summary>Show the relationship</summary><p class="formula">${m.law}</p></details><p class="muted">Teaching model v1 · Exact values in the journal; display values rounded.</p></details>`;}
const stages=['notice','predict','build','test','compare','explain','transfer1','transfer2','done'];const stageNames={notice:'Notice',predict:'Predict',build:'Build a fair test',test:'Test',compare:'Compare',explain:'Explain',transfer1:'Apply · new context',transfer2:'Apply · new constraint',done:'Discovery'};
function energyBuilder(r){const draft=r.energyDraft||{supply:'',demand:'',margin:''};const op=(id)=>`<select id="energy-${id}" aria-label="${id} operation"><option value="">Choose operation</option>${[['+','add'],['*','multiply'],['-','subtract'],['/','divide']].map(([v,t])=>`<option value="${v}" ${draft[id]===v?'selected':''}>${t}</option>`).join('')}</select>`;return `<div class="model-editor"><h3>Construct your energy model</h3><p>Use units to assemble the model before running the night.</p><label class="field">Delivered energy: storage ${op('supply')} efficiency</label><label class="field">Demand: load ${op('demand')} hours</label><label class="field">Margin: delivered energy ${op('margin')} demand</label>${button(r.energyModel?'✓ Model checked':'Check my model','energy-check','secondary full')}<p class="muted">${r.energyModel?'Your constructed model is ready to test.':'Power (W) multiplied by time (h) gives energy (Wh).'}</p></div>`;}
function missionView(){const m=currentMission(),r=currentRun(),model=adapters[m.adapter],q=questionFor(m,r),transfer=transferPlan(m,r),last=(transfer?transferTrials(r):r.trials).at(-1),interactive=r.stage==='test',display=ui.replay??last;
 let panel='';
 if(r.stage==='notice')panel=`<p class="eyebrow">MISSION BRIEF</p><h2>${m.title}</h2><p>${m.story}</p><div class="pip-note">${robotSvg()}<p>${lesson(m)}</p></div><div class="bridge"><b>Before we begin</b><p>Near and far compare positions. A trial is one test. A fair comparison changes one thing.</p>${m.prerequisites.length?`<p>Helpful preparation: ${m.prerequisites.map(id=>`<button class="term" data-action="start" data-id="${id}">${byId[id].title}</button>`).join(', ')}</p>`:''}</div>${button('Make a prediction →','next','primary full')}`;
 else if(r.stage==='test')panel=`<p class="eyebrow">YOUR EXPERIMENT</p><h2>${m.target?'Find a design that works':'Change one thing. Watch closely.'}</h2><p>${m.target?`Target: ${m.target[0]}–${m.target[1]} ${model.outUnit} (${model.output.toLowerCase()}).`:`Try ${m.compare[0]} and ${m.compare[1]} ${model.unit}. Keep everything else fixed.`}</p>${m.id==='cargo-budget'?'<p class="constraint">Parts budget: use height 0.30 m or lower.</p>':''}${m.adapter==='energy'?energyBuilder(r):''}${controls(m.adapter,r.input,!!ui.animation)}<div class="run-buttons">${button(ui.animation?(ui.paused?'Resume test':'Pause'):'Run test','run','primary',m.adapter==='energy'&&!r.energyModel?'disabled':'')}${button('Reset scene','reset','secondary')}</div><p class="muted">${r.trials.length} saved trial${r.trials.length===1?'':'s'} · reset keeps your evidence.</p>${last?`<div class="result-card"><small>${model.output}</small><strong>${round(last.value)} ${model.outUnit}</strong>${m.target?`<span>${insideBay(last.value,...m.target)?'✓ Within the target':'↻ Try another setting'}</span>`:''}</div>`:''}${button('Compare my evidence →','compare','secondary full',(!canCompare(m,r)||ui.animation)?'disabled':'')}`;
 else if(r.stage==='done'){const state=skillState(r),all=CATEGORIES.every(k=>r.evidence[k]);panel=`<div class="completion-icon">✦</div><p class="eyebrow">DISCOVERY RECORDED</p><h2>${r.completed?'A little more of the island is alive.':'Your evidence is recorded.'}</h2><p>${esc(m.skill)} · ${r.completed?'mission complete':'keep investigating'}</p>${badge(state,all?'success':'')}<p>${all?'You predicted, made a fair test, interpreted, explained, and applied the idea in two new contexts.':'Your discovery is saved. Some checks used help; revisit those checks to demonstrate the idea independently.'}</p><div class="evidence-grid">${CATEGORIES.map(k=>`<span class="${r.evidence[k]?'earned':''}">${r.evidence[k]?'✓':'○'} ${k.replace('transfer','Apply ')}</span>`).join('')}</div>${!all?button('Practice checks needing evidence','retry','primary full'):button('Explore the next mission →','next-mission','primary full')}${button('Open field journal','nav','secondary full','data-view="journal"')}`;}
 else panel=`<p class="eyebrow">${stageNames[r.stage].toUpperCase()}</p>${transfer?`<h2>${transfer.title}</h2><p>${transfer.story}</p><p class="constraint">New bay: ${transfer.target[0]}–${transfer.target[1]} m beyond the exit.</p>${controls(m.adapter,r.input,!!ui.animation)}<div class="run-buttons">${button(ui.animation?(ui.paused?'Resume test':'Pause'):'Test transfer design','run','primary')}${button('Reset scene','reset','secondary')}</div>${last?`<div class="result-card"><small>Transfer stopping distance</small><strong>${round(last.value)} m</strong><span>${insideBay(last.value,...transfer.target)?'✓ Within the new bay':'Try another ramp height'}</span></div>`:''}${trialTable(transferTrials(r),m.adapter,true)}`:''}${choices(q,r)}${r.stage==='explain'?`<label class="note-label">Your own explanation (optional; saved for adult review)<textarea id="explanation" rows="3" maxlength="1000" placeholder="I noticed… My evidence is…">${esc(r.notes)}</textarea></label><p class="muted">Writing is saved, not automatically graded. Use the evidence choice above for this check.</p>`:''}${ui.feedback?`<div class="feedback ${ui.feedback.ok?'good':'try'}" role="status">${esc(ui.feedback.text)}</div>`:''}${ui.feedback?.ok?button('Continue →','next','primary full'):button('Check my idea','check','primary full',ui.choice===null||!transferSatisfied(m,r)||ui.animation?'disabled':'')}${button('A little help','hint','text-button')}${r.assistance[r.stage]?'<p class="assistance">Supported attempt · this check will need an independent retry.</p>':''}`;
 const visibleInput=ui.progress>0?(display?.input??r.input):r.input;
 const resultArea=`<div class="scene-header"><span class="live-dot"></span><span>${model.label}</span><span>${ui.animation?ui.paused?'Paused':'Test running':ui.progress===1?'Trial recorded':'Ready to investigate'}</span></div><div id="scene">${scene(m.adapter,visibleInput,display,ui.progress,transfer?.target??m.target,r.trials.at(-2))}</div><div class="scene-caption">${m.adapter==='plant'?'Seven simulated days · three plants per condition':m.adapter==='energy'?'Ten simulated hours · solar output is zero at night':m.adapter==='ramp'?'Schematic · vertical scale exaggerated · distance measured from ramp exit':'One setting changes. One useful question.'}</div>`;
 return `<section class="content mission-content">${button('← '+regionOf(m).name,'region','back',`data-id="${m.region}"`)}<div class="mission-title"><div><p class="eyebrow">${regionOf(m).name.toUpperCase()} / EXPERIMENT ${String(m.index+1).padStart(2,'0')}</p><h1>${m.title}</h1></div>${button('◖ Read aloud','narrate','secondary')}</div><ol class="stepper" aria-label="Mission progress">${['notice','predict','build','test','compare','explain','transfer1','done'].map((s,i)=>`<li class="${stages.indexOf(r.stage)>=stages.indexOf(s)?'reached':''} ${r.stage===s?'current':''}" ${r.stage===s?'aria-current="step"':''}><span>${i+1}</span>${s==='transfer1'?'Apply':stageNames[s]}</li>`).join('')}</ol><div class="lab-layout"><div class="lab-main"><div class="scene-card">${resultArea}</div>${r.trials.length?`<div class="evidence-panel"><div class="panel-heading"><h2>Your trial notebook</h2>${badge(r.trials.length+' saved')}</div>${chart(r.trials)}${r.stage==='test'?`<div class="evidence-picker"><h3>Choose two trials to compare</h3><p class="muted">Change one setting. Keep the other conditions the same.</p>${r.trials.map((t,i)=>button(`${(r.compareSelection||[]).includes(t.id)?'✓':'○'} Trial ${i+1}: ${round(t.input)} ${model.unit}`,'select-trial',(r.compareSelection||[]).includes(t.id)?'secondary selected':'secondary',`data-id="${t.id}" aria-pressed="${(r.compareSelection||[]).includes(t.id)}"`)).join('')}</div>`:''}${trialTable(r.trials,m.adapter)}${timeSeries(last,m.adapter)}</div>`:''}${modelCard(m.adapter)}<details class="model-card"><summary>Meet the idea / glossary</summary><p>${lesson(m)}</p><div class="terms">${Object.entries(glossary).filter(([k])=>(m.vocabulary||['trial','variable','force','energy','model','fair']).includes(k)).map(([k,v])=>`<button class="term" data-action="term" data-term="${k}">${k}</button>`).join('')}</div></details></div><aside class="task-panel" aria-label="Current mission step">${panel}</aside></div></section>`;
}
function canCompare(m,r){return hasSelectedFairPair(r)&&(!m.target||r.trials.some(t=>insideBay(t.value,...m.target)&&(m.id!=='cargo-budget'||t.input<=.3)));}
function freeLab(){const l=ui.lab,model=adapters[l.adapter],last=l.trials.at(-1);return `<section class="content">${heading('YOUR INVENTION WORKSHOP',l.coop?'Co-op Lab':'Free Lab','Change a design, compare results, and keep your inventions.',button(l.coop?'Solo lab':'Shared-device co-op','coop','secondary'))}<div class="lab-tabs" role="group" aria-label="Choose an experiment">${Object.entries(adapters).map(([id,m])=>button(m.label,'lab-adapter',l.adapter===id?'selected':'',`data-id="${id}"`)).join('')}</div>${l.coop?`<div class="coop-banner"><b>Pass the device. Rotate the jobs.</b><p>${['Designer','Builder','Tester','Explainer'].map((role,i)=>`${role}: ${esc(data.profiles[(i+l.trials.length)%data.profiles.length].name)}`).join(' · ')}</p><p>Discuss a prediction before each run. Each explorer demonstrates skills in their own profile’s missions; a team experiment gives no automatic mastery.</p></div>`:''}<div class="lab-layout"><div class="lab-main"><div class="scene-card"><div class="scene-header">${model.label}<span>Exploration · no mastery awarded</span></div><div id="scene">${scene(l.adapter,ui.progress>0?(ui.replay?.input??last?.input??l.input):l.input,ui.replay??last,ui.progress,null,l.trials.at(-2))}</div></div><div class="evidence-panel"><h2>Invention trials</h2>${chart(l.trials)}${trialTable(l.trials,l.adapter)}${timeSeries(last,l.adapter)}</div>${modelCard(l.adapter)}</div><aside class="task-panel"><p class="eyebrow">BUILD SOMETHING. LEARN SOMETHING.</p><h2>${model.label}</h2>${controls(l.adapter,l.input,!!ui.animation,l.options)}${l.adapter==='ramp'?`<label class="field">Lane resistance<select id="lab-resistance" ${ui.animation?'disabled':''}><option value="0.2" ${!l.options.resistance||l.options.resistance===.2?'selected':''}>Standard · 0.20</option><option value="0.1" ${l.options.resistance===.1?'selected':''}>Lower · 0.10</option><option value="0.4" ${l.options.resistance===.4?'selected':''}>Higher · 0.40</option></select></label>`:''}${l.adapter==='energy'?`<div class="model-editor"><h3>Build the energy model</h3><label class="field">Stored energy (Wh)<input id="lab-storage" type="number" min="100" max="2000" step="100" value="${l.options.storage??800}" ${ui.animation?'disabled':''}></label><label class="field">Delivery efficiency<select id="lab-efficiency" ${ui.animation?'disabled':''}>${[.6,.8,1].map(v=>`<option value="${v}" ${v===(l.options.efficiency??.8)?'selected':''}>${v*100}%</option>`).join('')}</select></label><p>Margin = storage × efficiency − load × 10 hours. Modify a parameter, predict its effect, and inspect the ledger.</p></div>`:''}<div class="run-buttons">${button(ui.animation?(ui.paused?'Resume':'Pause'):'Run experiment','run','primary')}${button('Reset','reset','secondary')}</div>${last?`<div class="result-card"><small>${model.output}</small><strong>${round(last.value)} ${model.outUnit}</strong></div><label class="field">Name this invention<input id="invention-name" maxlength="50" placeholder="My ${model.label.toLowerCase()}"></label>${button('Save invention ✧','save-invention','secondary full')}`:''}<p class="muted">Free Lab is always open. Saved inventions and skill evidence are kept separately.</p></aside></div></section>`;}
function journal(){const p=profile(),seen=missions.filter(m=>p.runs[m.id]),dem=seen.filter(m=>['Demonstrated','Retained'].includes(skillState(p.runs[m.id])));return `<section class="content">${heading('THE FIELD JOURNAL','Small experiments. Big discoveries.',`${esc(p.name)}’s notebook · ${seen.reduce((n,m)=>n+p.runs[m.id].trials.length,0)} recorded trials`)}<div class="journal-stats"><div><strong>${achievements()}</strong><span>Discoveries made</span></div><div><strong>${dem.length}</strong><span>Skills demonstrated</span></div><div><strong>${p.inventions.length}</strong><span>Inventions saved</span></div></div><div class="journal-columns"><div><h2>Evidence & next steps</h2>${seen.length?seen.map(m=>{const r=p.runs[m.id],state=skillState(r),due=r.completedAt&&Date.now()-r.completedAt>86400000;return `<details class="journal-entry"><summary><span>${regionOf(m).icon} &nbsp;${m.title}</span>${badge(state,state==='Demonstrated'||state==='Retained'?'success':'')}</summary><div class="evidence-grid">${CATEGORIES.map(k=>`<span class="${r.evidence[k]?'earned':''}">${r.evidence[k]?'✓':'○'} ${k}</span>`).join('')}</div>${trialTable(r.trials,m.adapter,true)}${Object.entries(r.transferTrials||{}).map(([stage,trials])=>`<h3>${stage==='transfer1'?'New trolley delivery':'Sorting-ramp transfer'}</h3>${trialTable(trials,m.adapter,true)}`).join('')}${r.notes?`<p><b>Explorer’s explanation (adult review):</b> ${esc(r.notes)}</p>`:''}<p>Help used: ${[...new Set((r.hintHistory||[]).map(h=>h.stage).concat(Object.keys(r.assistance).filter(k=>r.assistance[k])))].join(', ')||'none'}.</p><p class="muted">Mission completion and demonstrated understanding are separate. ${m.review}.</p>${button('Open mission','start','secondary',`data-id="${m.id}"`)}${due&&CATEGORIES.every(k=>r.evidence[k])?button('Later-session review','review','secondary',`data-id="${m.id}"`):''}</details>`;}).join(''):`<div class="empty-state">${robotSvg()}<h3>Your first page is waiting.</h3><p>Run an experiment and Pip will record the results here.</p>${button('Try Rover Rescue','start','primary','data-id="rover-rescue"')}</div>`}</div><div><h2>My inventions</h2>${p.inventions.length?p.inventions.map((inv,i)=>`<article class="invention"><span>⚒</span><h3>${esc(inv.name)}</h3><p>${adapters[inv.adapter]?.label} · ${round(inv.result.value)} ${adapters[inv.adapter]?.outUnit}</p>${button('Rebuild','load-invention','secondary',`data-index="${i}"`)}</article>`).join(''):'<p class="empty">Visit Free Lab to build and save an invention.</p>'}<div class="adult-note"><h3>For grown-ups</h3><p>Six independent checks support a “Demonstrated” label. Answer-revealing help never earns independent evidence. Later-session review is offered after a day.</p><p>These are original early-access investigations, not a complete or certified K–12 curriculum. Educator review and learner playtesting remain outstanding.</p>${button('Backup & profiles','nav','secondary','data-view="settings"')}</div></div></div></section>`;}
function arcadeView(){if(ui.arcade)return arcadeGame();const modes=[['cargo','Cargo Catch','Land a supply rover in three different delivery bays.','rover-rescue','⚙'],['signal','Signal Sprint','Match the receiver’s wavelength. Timing is optional.','signal-sprint','ϟ'],['habitat','Habitat Balance','Respond to resource changes with a supported explanation.','habitat-supply','♧'],['buildoff','Build-Off','Compare two ramp designs that solve the same delivery brief.','rover-rescue','⚒']];return `<section class="content">${heading('THE DISCOVERY ARCADE','Play with what you know.','Untimed challenges. Unlimited retries. A new way to use an idea.')}<div class="arcade-grid">${modes.map(([id,title,desc,prereq,icon])=>{const unlocked=['Demonstrated','Retained'].includes(skillState(profile().runs[prereq]));return `<article class="arcade-card"><div class="arcade-icon">${icon}</div><h2>${title}</h2><p>${desc}</p>${badge(unlocked?'Ready to play':'Preparation available',unlocked?'success':'')}<div class="arcade-actions">${button(unlocked?'Play challenge →':'Supported preview →','arcade-start','primary',`data-id="${id}" data-scored="${unlocked}"`)}${!unlocked?button('Learn: '+byId[prereq].title,'start','text-button',`data-id="${prereq}"`):''}</div><p class="muted">Best: ${profile().arcade[id]??0} · practice scores never award science mastery</p></article>`;}).join('')}</div></section>`;}
function arcadeGame(){const a=ui.arcade;let adapter=a.id==='signal'?'wave':a.id==='habitat'?'habitat':'ramp',target=a.id==='signal'?[5,2,10][a.round%3]:a.id==='buildoff'?1:[1,2,1.5][a.round%3];const done=a.round>=3;return `<section class="content">${button('← Arcade','arcade-exit','back')}${heading(a.scored?'PRACTICE CHALLENGE':'SUPPORTED PREVIEW',({cargo:'Cargo Catch',signal:'Signal Sprint',habitat:'Habitat Balance',buildoff:'Build-Off'})[a.id],`Round ${Math.min(3,a.round+1)} of 3 · ${a.score} points · no timer`)}${done?`<div class="celebration"><div class="completion-icon">✧</div><h2>Challenge complete!</h2><p>${a.score} points ${a.scored?'saved to this explorer':'in supported preview'}.</p>${button('Return to arcade','arcade-exit','primary')}</div>`:`<div class="lab-layout"><div class="scene-card"><div id="scene">${scene(adapter,a.input,a.result,a.result?1:0,adapter==='ramp'?[target-.05,target+.05]:null)}</div>${a.result?`<p class="scene-caption">Result: ${round(a.result.value)} ${adapters[adapter].outUnit}</p>`:''}</div><aside class="task-panel"><h2>${a.id==='habitat'?`Supply ${[4,8,6][a.round]} animals`:`Target: ${target} ${adapters[adapter].outUnit}`}</h2><p>${a.id==='buildoff'?`Design ${a.round+1}: use resistance ${[.2,.4,.1][a.round]}. Land at the same bay with a different ramp.`:a.id==='habitat'?'Each animal needs 5 units of food each day. Choose the exact food budget.':'Adjust one setting and test your design.'}</p>${controls(adapter,a.input)}${button('Test my design','arcade-test','primary full')}${a.feedback?`<div class="feedback ${a.passed?'good':'try'}">${esc(a.feedback)}</div>`:''}${a.passed?button('Next round →','arcade-next','secondary full'):''}</aside></div>`}</section>`;}
function settings(){const p=profile();return `<section class="content settings">${heading('MAKE YOURSELF AT HOME','Explorers & settings','Profiles and progress stay in this browser. No account or personal information needed.')}<div class="settings-grid"><section class="settings-panel"><h2>Choose an explorer</h2><div class="profiles">${data.profiles.map(x=>`<button class="explorer ${x.id===p.id?'selected':''}" data-action="profile" data-id="${x.id}" aria-pressed="${x.id===p.id}"><span>${esc(x.avatar)}</span><b>${esc(x.name)}</b>${x.id===p.id?'<small>Playing now</small>':''}</button>`).join('')}</div><form id="new-profile"><label class="field">Explorer nickname<input id="profile-name" maxlength="30" required placeholder="e.g. River" autocomplete="off"></label><label class="field">Explorer<select id="profile-avatar"><option>🧑🏽‍🚀</option><option>👩🏿‍🔬</option><option>👨🏻‍🔬</option><option>👩🏽‍🚀</option><option>🧑🏼‍🔬</option><option>🤖</option></select></label><button class="secondary" type="submit" ${data.profiles.length>=12?'disabled':''}>Add explorer</button></form>${data.profiles.length>1?button('Delete this explorer’s local progress','delete-profile','danger text-button'):''}</section><section class="settings-panel"><h2>Comfort & reading</h2><label class="field">Learning pathway<select id="band">${['All explorers','K–2','3–5','6–8','9–12'].map(b=>`<option ${data.settings.band===b?'selected':''}>${b}</option>`).join('')}</select></label><p class="muted">A guide for where to begin; all investigations stay available.</p><label class="toggle"><input id="large-text" type="checkbox" ${data.settings.large?'checked':''}> Larger text</label><label class="toggle"><input id="reduced-motion" type="checkbox" ${data.settings.reduced?'checked':''}> Reduce animation</label><label class="toggle"><input id="technical-theme" type="checkbox" ${data.settings.technical?'checked':''}> Night / technical theme</label>${button('Read a sample aloud','sample-narration','secondary')}<p class="muted">Read-aloud uses your device’s available voice. Every spoken message is also written on screen. English content.</p><h3>Readiness bridge</h3><p>New to experiments? Compare two pushes, then learn what makes a fair test.</p>${button('Start with First Move','start','secondary','data-id="first-move"')}</section><section class="settings-panel"><h2>Keep your discoveries</h2><p>Export a backup to move explorers between devices. Import merges by explorer ID and keeps a separate imported copy if progress differs.</p><div class="run-buttons">${button('Export backup','export','primary')}<label class="button secondary">Import backup<input id="import-save" type="file" accept="application/json,.json" hidden></label></div><p class="muted">Storage: ${storageMode}. ${navigator.onLine?'Online':'Offline'}. Export regularly if this device clears browser data.</p>${button('Export recovery archives','export-recovery','text-button')}<h3>About this release</h3><p>35 playable investigations across six regions, with guided missions, a free lab and four arcade challenges.</p><p>Local shared-device co-op is in Build. Online co-op and account sync are not included. Device export/import is available.</p><p>Original curriculum in early access. No claims of complete standards coverage or proven learning outcomes.</p><a href="https://chiokebuckley-art.github.io/engineering-quest/" target="_blank" rel="noopener">Engineering Quest ↗</a> · <a href="https://chiokebuckley-art.github.io/wordraiders/" target="_blank" rel="noopener">Word Raiders ↗</a></section></div></section>`;}
function render(){document.body.classList.toggle('large-text',!!data.settings.large);document.body.classList.toggle('technical',!!data.settings.technical);document.body.classList.toggle('reduced',!!data.settings.reduced);let views={explore:mapView,courses:coursesView,region:regionView,mission:missionView,lab:freeLab,journal,arcade:arcadeView,settings};app.innerHTML=shell((views[ui.view]||mapView)());}
function stopAnimation(){if(ui.animation)cancelAnimationFrame(ui.animation.frame);ui.animation=null;ui.paused=false;ui.replay=null;}
function animate(result,adapter,target=null,onComplete){stopAnimation();ui.replay=result;if(data.settings.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches){ui.progress=1;onComplete?.();render();return;}ui.animation={elapsed:0,last:performance.now(),frame:0};const duration=adapter==='plant'||adapter==='energy'?3500:Math.min(5500,Math.max(2000,result.duration*700));render();function frame(now){if(!ui.animation)return;const a=ui.animation;if(!ui.paused)a.elapsed+=Math.min(100,now-a.last);a.last=now;ui.progress=Math.min(1,a.elapsed/duration);const targetEl=$('#scene');if(targetEl)targetEl.innerHTML=scene(adapter,result.input,result,ui.progress,target);if(ui.progress<1)a.frame=requestAnimationFrame(frame);else{ui.animation=null;onComplete?.();render();}}ui.animation.frame=requestAnimationFrame(frame);}
function runExperiment(){if(ui.animation){ui.paused=!ui.paused;render();return;}const lab=ui.view==='lab',m=lab?null:currentMission(),r=lab?ui.lab:currentRun(),adapter=lab?r.adapter:m.adapter;const transfer=lab?null:transferPlan(m,r);if(!lab&&((r.stage!=='test'&&!transfer)||(adapter==='energy'&&!r.energyModel)))return;const result={...simulate(adapter,r.input,lab?r.options:{}),id:crypto.randomUUID(),at:Date.now()};if(transfer){r.transferTrials??={};r.transferTrials[r.stage]??=[];r.transferTrials[r.stage].push(result);}else{r.trials.push(result);if(!lab)r.trialIds.push(result.id);}if(lab)ui.lab.trials=r.trials;save(transfer?'transfer-trial':'trial',{stage:r.stage,configuration:{input:r.input,options:lab?r.options:{}},measurements:result,hintFlags:lab?{}:r.assistance});animate(result,adapter,transfer?.target??m?.target);}
function setInput(value){const a=ui.arcade;const holder=ui.view==='arcade'?a:ui.view==='lab'?ui.lab:currentRun();const id=ui.view==='arcade'?(a.id==='signal'?'wave':a.id==='habitat'?'habitat':'ramp'):ui.view==='lab'?ui.lab.adapter:currentMission().adapter;const m=adapters[id];holder.input=round(Math.max(m.min,Math.min(m.max,value)),6);if(a){a.passed=false;a.feedback='';a.result=null;}ui.progress=0;ui.replay=null;const out=$('#input-output');if(out)out.textContent=holder.input+' '+m.unit;const slider=$('#experiment-input');if(slider)slider.value=holder.input;$('#scene').innerHTML=scene(id,holder.input,null,0,ui.view==='mission'?(transferPlan(currentMission(),currentRun())?.target??currentMission().target):null);save('configuration',{input:holder.input});}
function moveNext(){const r=currentRun();advanceRun(r);beginTransfer(r,currentMission());if(transferPlan(currentMission(),r)){ui.progress=0;ui.replay=null;}ui.choice=null;ui.feedback=null;save('step',{stage:r.stage,evidence:r.evidence});render();document.querySelector('.task-panel h2')?.setAttribute('tabindex','-1');document.querySelector('.task-panel h2')?.focus();}
function checkAnswer(){const m=currentMission(),r=currentRun();if(!transferSatisfied(m,r)){notify('Test a design that reaches the new bay before explaining it.');return;}const q=questionFor(m,r),ok=ui.choice===q.correct;const category={build:'fair',compare:'interpret'}[r.stage]||r.stage;if(r.reviewing){if(ok&&!r.assistance[r.stage]){r.retainedAt=Date.now();r.reviewFailed=false;}else if(!ok){r.reviewFailed=true;}}else recordCheck(r,category,ok,!!r.assistance[r.stage]);ui.feedback=ok?{ok:true,text:r.assistance[r.stage]?'That fits the evidence. This supported check is saved; you can revisit it independently later.':'That fits the evidence. Your independent check is recorded.'}:{ok:false,text:'Take another look at what changed and what stayed the same. Compare the measurements, then try again.'};storeFeedback(r,ui.feedback);save('assessment',{category,correct:ok,assisted:!!r.assistance[r.stage],selected:ui.choice,item:{stage:r.stage,variant:r.attempts[r.stage]||0,prompt:q.prompt,options:q.options},trialIds:(r.compareSelection||[]).slice(),transferTrialIds:transferTrials(r).map(t=>t.id),evidence:r.evidence});render();}
function narrate(text){if(!('speechSynthesis'in window)){notify('Read-aloud is unavailable on this device. All instructions remain on screen.');return;}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='en-US';utterance.rate=.9;utterance.onerror=()=>notify('The voice could not start. You can use the written instructions.');speechSynthesis.speak(utterance);}
app.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;
 try{switch(action){
 case'nav':{let v=el.dataset.view;if(v==='test'){startMission(profile().lastMission||data.lastMission||'rover-rescue');return;}goto(v);break;}
 case'region':goto('region',{region:el.dataset.id});break;
 case'start':startMission(el.dataset.id);break;
 case'islands':$('#region-grid').scrollIntoView({behavior:'smooth'});break;
 case'next':moveNext();break;
 case'choice':ui.choice=Number(el.dataset.value);chooseAnswer(currentRun(),ui.choice);ui.feedback=null;save('answer-choice',{stage:currentRun().stage,choice:ui.choice});render();document.querySelector('[data-action=check]')?.focus();break;
 case'check':checkAnswer();break;
 case'hint':{const m=currentMission(),r=currentRun(),q=questionFor(m,r);r.assistance[r.stage]=true;r.hintHistory??=[];r.hintHistory.push({stage:r.stage,at:Date.now()});ui.feedback={ok:false,text:'Pip’s hint: '+q.options[q.correct]};storeFeedback(r,ui.feedback);save('hint',{stage:r.stage});render();break;}
 case'run':runExperiment();break;
 case'energy-check':{const r=currentRun();r.energyModel=validEnergyConstruction(r.energyDraft);save('energy-model-construction',{draft:r.energyDraft,valid:r.energyModel});render();notify(r.energyModel?'Model checked. Now test its predictions against the ledger.':'Check the units: efficiency is a fraction; watts multiplied by hours gives watt-hours. The margin is what remains after demand.');break;}
 case'adjust':{const id=ui.view==='arcade'?(ui.arcade.id==='signal'?'wave':ui.arcade.id==='habitat'?'habitat':'ramp'):ui.view==='lab'?ui.lab.adapter:currentMission().adapter;setInput(Number($('#experiment-input').value)+Number(el.dataset.delta)*adapters[id].step);break;}
 case'reset':stopAnimation();ui.progress=0;render();break;
 case'select-trial':{toggleTrialSelection(currentRun(),el.dataset.id);save('evidence-selection',{trialIds:currentRun().compareSelection});render();break;}
 case'compare':if(canCompare(currentMission(),currentRun())){enterStage(currentRun(),'compare');ui.choice=null;ui.feedback=null;save('compare');render();}break;
 case'replay':{const r=ui.view==='lab'?ui.lab:currentRun(),result=r.trials[Number(el.dataset.index)];animate(result,result.model,ui.view==='mission'?(transferPlan(currentMission(),currentRun())?.target??currentMission().target):null);ui.replay=result;break;}
 case'retry':{beginRetry(currentRun());beginTransfer(currentRun(),currentMission());ui.choice=null;ui.feedback=null;save('independent-retry');render();break;}
 case'next-mission':{const m=currentMission(),next=missions[m.index+1]||missions[0];startMission(next.id);break;}
 case'narrate':{const m=currentMission(),r=currentRun();narrate((questionFor(m,r)?.prompt||m.story)+' '+(r.stage==='notice'?lesson(m):''));break;}
 case'sample-narration':narrate('Welcome to Discovery Islands. I’m Pip. Let’s make a prediction, test an idea, and see what happens.');break;
 case'term':notify(el.dataset.term+': '+glossary[el.dataset.term]);narrate(glossary[el.dataset.term]);break;
 case'lab-adapter':stopAnimation();ui.lab={...ui.lab,adapter:el.dataset.id,input:adapters[el.dataset.id].initial,options:{},trials:[]};ui.progress=0;render();break;
 case'coop':ui.lab.coop=!ui.lab.coop;if(data.profiles.length<2&&ui.lab.coop)notify('Add another explorer in Settings for separate names and progress. One person can also rotate all four roles.');render();break;
 case'save-invention':{const l=ui.lab;profile().inventions.push({id:crypto.randomUUID(),name:$('#invention-name').value.trim()||'My '+adapters[l.adapter].label,adapter:l.adapter,input:l.trials.at(-1).input,options:l.trials.at(-1).options,result:l.trials.at(-1),at:Date.now()});await save('invention');notify('Invention saved in your field journal.');break;}
 case'load-invention':{const i=profile().inventions[Number(el.dataset.index)];goto('lab',{lab:{adapter:i.adapter,input:i.input,options:i.options,trials:[i.result],coop:false},progress:1});break;}
 case'profile':data.active=el.dataset.id;data.lastMission=null;await save('profile-switch');ui.lab={adapter:'ramp',input:.2,options:{},trials:[],coop:false};ui.arcade=null;render();break;
 case'delete-profile':{if(el.dataset.confirm!=='yes'){el.dataset.confirm='yes';el.textContent='Confirm deletion of '+profile().name+' on this device';return;}const id=data.active;data.profiles=data.profiles.filter(p=>p.id!==id);data.active=data.profiles[0].id;data.lastMission=null;await deleteProfileEvents(id);await save('profile-deleted');render();break;}
 case'export-recovery':downloadJSON(await recoveryExport(),'science-quest-recovery-archives.json');notify('Recovery data exported.');break;
 case'export':{await save('export');const events=await getEvents(),blob=new Blob([JSON.stringify({...data,events},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='science-quest-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);notify('Backup exported. Keep it somewhere safe.');break;}
 case'review':{const id=el.dataset.id,r=profile().runs[id];beginReview(r);beginTransfer(r,byId[id]);ui.mission=id;await save('retention-review-start');goto('mission',{mission:id});notify('Later-session review: apply the idea again without a hint.');break;}
 case'arcade-start':{const id=el.dataset.id;ui.arcade={id,scored:el.dataset.scored==='true',round:0,score:0,input:id==='signal'?2:id==='habitat'?20:.2};render();break;}
 case'arcade-exit':ui.arcade=null;render();break;
 case'arcade-test':{const a=ui.arcade,id=a.id==='signal'?'wave':a.id==='habitat'?'habitat':'ramp';a.result=simulate(id,a.input,a.id==='buildoff'?{resistance:[.2,.4,.1][a.round]}:{});const target=a.id==='signal'?[5,2,10][a.round]:a.id==='habitat'?[4,8,6][a.round]:a.id==='buildoff'?1:[1,2,1.5][a.round];a.passed=Math.abs(a.result.value-target)<.051;a.feedback=a.passed?'Design delivered! Explain the relationship to a partner, then try the next brief.':'Not quite at the target. Use the result to choose a new setting. Unlimited tries.';render();break;}
 case'arcade-next':{const a=ui.arcade;if(!a.passed)return;a.score+=100;a.round++;a.passed=false;a.feedback='';a.result=null;if(a.round===3&&a.scored){profile().arcade[a.id]=Math.max(profile().arcade[a.id]||0,a.score);save('arcade',{game:a.id,score:a.score});}render();break;}
 case'update':await save('before-update');swUpdate.postMessage('ACTIVATE');break;
 }}catch(error){notify('That action could not finish: '+error.message);}
});
app.addEventListener('input',e=>{if(e.target.id==='experiment-input'&&!ui.animation)setInput(Number(e.target.value));if(e.target.id==='explanation'){currentRun().notes=e.target.value;save('explanation-note');}});
app.addEventListener('change',async e=>{const id=e.target.id;try{if(id.startsWith('energy-')){const r=currentRun();r.energyDraft??={};r.energyDraft[id.slice(7)]=e.target.value;r.energyModel=false;save('energy-model-edit');render();}if(['large-text','reduced-motion','technical-theme'].includes(id)){data.settings[{'large-text':'large','reduced-motion':'reduced','technical-theme':'technical'}[id]]=e.target.checked;save('settings');render();}if(id==='band'){data.settings.band=e.target.value;save('settings');const next=missions.find(m=>m.band===e.target.value);if(next){data.lastMission=next.id;profile().lastMission=next.id;notify('Suggested starting point: '+next.title+'. All missions remain available.');}}if(id==='lab-resistance'){ui.lab.options.resistance=Number(e.target.value);ui.progress=0;}if(id==='lab-efficiency')ui.lab.options.efficiency=Number(e.target.value);if(id==='lab-storage'){const v=Number(e.target.value);ui.lab.options.storage=Math.min(2000,Math.max(100,Number.isFinite(v)?v:800));e.target.value=ui.lab.options.storage;}if(id==='import-save'){const file=e.target.files[0];if(!file)return;if(file.size>8e6)throw Error('Backup is too large. Maximum 8 MB.');const imported=validateSave(JSON.parse(await file.text()));for(const p of imported.profiles){for(const [key,r]of Object.entries(p.runs)){if(!byId[key]||r.mission!==key)throw Error('Unknown mission in backup.');simulate(byId[key].adapter,r.input);for(const t of r.trials)if(!adapters[t.model])throw Error('Unknown model in backup.');}}const incoming=[];const remap=new Map();for(const p of imported.profiles){const existing=data.profiles.find(x=>x.id===p.id);if(!existing)incoming.push(p);else if(JSON.stringify(existing)!==JSON.stringify(p)){const clone=structuredClone(p);clone.id=crypto.randomUUID();clone.name=(p.name+' (imported)').slice(0,30);remap.set(p.id,clone.id);incoming.push(clone);}}if(data.profiles.length+incoming.length>12)throw Error('Import would exceed 12 explorers. Export and remove an unused local profile first.');const events=(imported.events||[]).map(ev=>remap.has(ev.profile)?{...ev,id:crypto.randomUUID(),profile:remap.get(ev.profile)}:ev);const merged=structuredClone(data);merged.profiles.push(...incoming);await replaceSaveWithEvents(merged,events);data=merged;await save('import');render();notify('Backup imported. Existing discoveries were preserved.');}}catch(error){notify('Could not import or change this setting: '+error.message);}});
app.addEventListener('submit',async e=>{if(e.target.id!=='new-profile')return;e.preventDefault();let name=$('#profile-name').value.trim();if(!name||data.profiles.length>=12)return;const p=makeProfile(name,$('#profile-avatar').value);data.profiles.push(p);data.active=p.id;data.lastMission=null;await save('profile-created');render();notify('Welcome, '+p.name+'!');});
window.addEventListener('online',()=>{if(data)render();});window.addEventListener('offline',()=>{if(data)render();});
function downloadJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function showRecovery(error){app.innerHTML=`<main class="content recovery"><h1>Your discoveries are protected.</h1><p>This browser’s saved data could not be opened. Nothing has been overwritten.</p><p>${esc(error.message)}</p><button id="download-recovery" class="primary">Download original save for recovery</button><label class="button secondary">Restore a valid backup<input id="recovery-import" type="file" accept="application/json,.json" hidden></label><button id="fresh-save" class="secondary">Archive the original and start fresh</button><p class="muted">Starting fresh preserves a recovery copy in this browser. Download it first if browser storage may be cleared.</p><div id="recovery-error" role="status"></div></main>`;
$('#download-recovery').onclick=async()=>{try{downloadJSON(await recoveryExport(),'science-quest-recovery.json');}catch(e){$('#recovery-error').textContent=e.message;}};
$('#fresh-save').onclick=async()=>{try{await archiveUnreadableSave();await init();}catch(e){$('#recovery-error').textContent='Could not preserve the original, so a new save was not started. '+e.message;}};
$('#recovery-import').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(file.size>8e6)throw Error('Backup exceeds 8 MB.');const incoming=validateSave(JSON.parse(await file.text()));for(const p of incoming.profiles)for(const r of Object.values(p.runs))migrateRun(r);const events=incoming.events||[];if(!Array.isArray(events)||events.some(e=>!e?.id||!e.profile))throw Error('Invalid evidence events.');await archiveUnreadableSave();await replaceSaveWithEvents(incoming,events);await init();}catch(e){$('#recovery-error').textContent=e.message;}};
}
async function init(){try{storageMode=await openStore();data=await loadSave();if(data){validateSave(data);for(const p of data.profiles)for(const r of Object.values(p.runs))migrateRun(r);}}catch(error){data=null;showRecovery(error);return;}if(!data){const p=makeProfile();data={version:1,profiles:[p],active:p.id,lastMission:null,settings:{band:'All explorers',large:false,reduced:false,technical:false}};await save('first-visit');}data.settings??={};render();if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(reg=>{if(reg.waiting){swUpdate=reg.waiting;render();}reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker.addEventListener('statechange',()=>{if(worker.state==='installed'&&navigator.serviceWorker.controller){swUpdate=worker;render();}});});}).catch(()=>notify('Offline installation is unavailable. You can still play online.'));let refreshing=false;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(swUpdate&&!refreshing){refreshing=true;location.reload();}});}}
init();
